// === Tab: mySketch ===
ArrayList<Particle> particles = new ArrayList<Particle>();

function setup() {
	colorMode(HSB);
	createCanvas(1024, 768);
	noStroke();
}

function draw() {
	background(0);
	for(i = 0; i < 6; i ++) {
		let hue = random(230);
		particles.add(new Particle((hue/100)+10,color(hue,255,200)));
	}
	for(particle p : particles){
		fill(p.color);
		/*if(p.x>width/2&&p.x-2<width/2){
			fill(255);
			ellipse(p.x, p.y, 16, 16);
		}*/
		ellipse(p.x, p.y, 8, 8);
		ellipse(width-p.x, p.y, 8, 8);
		p.yv-=0.1;
		p.x+=5;
		p.y-=p.yv;
		if(p.y>height-70) particles.remove(p);
	}
}

class Particle {
	color;
	x;
	y = height-70;
	yv;
	constructor(yv, color){
		this.color = color;
		this.yv = yv;
		this.x = width/6-(yv*20);
	}
}

